const state = {
  collected_at: new Date().toISOString(),
  source: 'opnsense',
  data: {
    interfaces: {},
    aliases: {},
    routes: {},
    dhcp_leases: {}
  }
};

try { state.data.interfaces = $('OPNsense: Get Interfaces').first().json; } catch(e) {}
try { state.data.aliases = $('OPNsense: Get Aliases').first().json; } catch(e) {}
try { state.data.routes = $('OPNsense: Get Routes').first().json; } catch(e) {}
try { state.data.dhcp_leases = $('OPNsense: Get DHCP Leases').first().json; } catch(e) {}

return [{ json: state }];

const fs = require('fs');
const path = '/path/to/vault/opnsense-state.json';

try {
  const content = fs.readFileSync(path, 'utf8');
  return [{ json: JSON.parse(content) }];
} catch (e) {
  // File doesn't exist yet — first run
  return [{ json: {} }];
}

// Compare current state with previous state to find changes
const current = $('Build State Object').first().json;
let previous = null;

try {
  const prevData = $('Read Previous State').first();
  if (prevData && prevData.json && prevData.json.data) {
    previous = prevData.json;
  }
} catch (e) {}

const diff = {
  has_changes: false,
  is_first_run: !previous,
  changes: [],
  current_state: current,
  previous_collected_at: previous?.collected_at || null
};

if (!previous) {
  diff.has_changes = true;
  diff.changes.push('Initial topology scan — no previous state found');
} else {
  const currIfaces = JSON.stringify(current.data.interfaces);
  const prevIfaces = JSON.stringify(previous.data.interfaces);
  if (currIfaces !== prevIfaces) {
    diff.has_changes = true;
    diff.changes.push('Interface configuration changed');
  }

  const currAliases = JSON.stringify(current.data.aliases);
  const prevAliases = JSON.stringify(previous.data.aliases);
  if (currAliases !== prevAliases) {
    diff.has_changes = true;
    diff.changes.push('Firewall aliases changed');
  }

  const currRoutes = JSON.stringify(current.data.routes);
  const prevRoutes = JSON.stringify(previous.data.routes);
  if (currRoutes !== prevRoutes) {
    diff.has_changes = true;
    diff.changes.push('Routing table changed');
  }

  const currDhcp = JSON.stringify(current.data.dhcp_leases);
  const prevDhcp = JSON.stringify(previous.data.dhcp_leases);
  if (currDhcp !== prevDhcp) {
    diff.has_changes = true;
    diff.changes.push('DHCP leases changed');
  }
}

return [{ json: diff }];

// Build the prompt for Claude Code
const diff = $('Diff: Detect Changes').first().json;
const state = diff.current_state;

const prompt = `You are a network documentation assistant for a homelab environment.

Here is the current infrastructure state collected from OPNsense:

\`\`\`json
${JSON.stringify(state.data, null, 2)}
\`\`\`

Detected changes since last scan:
${diff.changes.map(c => '- ' + c).join('\n')}

Please generate TWO outputs separated by the delimiter ===SPLIT===

OUTPUT 1: A YAML file (opnsense.yml) representing the current OPNsense state in a NetBox-compatible schema. Include:
- Device metadata (name, role, site, device_type)
- All interfaces with their IPs, subnets, VLAN assignments, and status
- Firewall aliases organized by type
- Static routes
- Active DHCP scopes with ranges

OUTPUT 2: A Markdown document (opnsense.md) for the Obsidian vault. Include:
- YAML frontmatter with tags, date, and aliases
- Human-readable summary of the OPNsense configuration
- Interface table (name, IP, VLAN, description)
- Notable firewall aliases
- DHCP scope summary
- A "Changes" section noting what changed in this scan
- Use wiki-links [[like this]] for cross-references to other homelab notes

Keep the tone concise and technical. Output the delimiter ===SPLIT=== on its own line with no spaces or extra characters.`;

// Base64 encode to safely pass through SSH without shell escaping issues
const base64Prompt = Buffer.from(prompt).toString('base64');

return [{ json: { prompt, base64Prompt } }];

const response = $json.stdout || $json.stderr || '';

// Try multiple delimiter variants in case Claude formats it differently
let splitIndex = response.indexOf('===SPLIT===');
if (splitIndex === -1) splitIndex = response.indexOf('=== SPLIT ===');
if (splitIndex === -1) splitIndex = response.indexOf('===split===');
if (splitIndex === -1) {
  const match = response.match(/={3}\s*SPLIT\s*={3}/i);
  if (match) splitIndex = match.index;
}

if (splitIndex === -1) {
  // Delimiter not found — skip writes to avoid wiping existing files
  console.error('===SPLIT=== not found in Claude output. Skipping writes.');
  return [
    { json: { type: 'yaml', content: null, base64Content: '', filename: 'opnsense.yml', skipped: true } },
    { json: { type: 'markdown', content: null, base64Content: '', filename: 'opnsense.md', skipped: true } }
  ];
}

const delimLen = response.match(/={3}\s*SPLIT\s*={3}/i)[0].length;

const yamlContent = response.substring(0, splitIndex).trim()
  .replace(/^```ya?ml\n?/, '').replace(/\n?```$/, '').trim();

const mdContent = response.substring(splitIndex + delimLen).trim()
  .replace(/^```markdown\n?/, '').replace(/\n?```$/, '').trim();

console.log('YAML length:', yamlContent.length);
console.log('MD length:', mdContent.length);

return [
  { json: { type: 'yaml', content: yamlContent, base64Content: Buffer.from(yamlContent).toString('base64'), filename: 'opnsense.yml', skipped: false } },
  { json: { type: 'markdown', content: mdContent, base64Content: Buffer.from(mdContent).toString('base64'), filename: 'opnsense.md', skipped: false } }
];

const diff = $('Diff: Detect Changes').first().json;
const date = new Date().toISOString().split('T')[0];
const time = new Date().toISOString().split('T')[1].split('.')[0];

const entry = `\n## ${date} ${time}\n\n${diff.changes.map(c => '- ' + c).join('\n')}\n`;
const base64Entry = Buffer.from(entry).toString('base64');

return [{ json: { entry, base64Entry } }];

const state = $('Build State Object').first().json;
const base64State = Buffer.from(JSON.stringify(state, null, 2)).toString('base64');
return [{ json: { base64State } }];
